begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(47);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values
('18210000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp182-confirm@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18210000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18210000-0000-0000-0000-000000000002','18210000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18210000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18210000-0000-0000-0000-000000000004','18210000-0000-0000-0000-000000000001','18210000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18210000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18210000-0000-0000-0000-000000000005','18210000-0000-0000-0000-000000000001','18210000-0000-0000-0000-000000000003',now());
insert into public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at) values ('mcp182-browser','mcp182-browser','18210000-0000-0000-0000-000000000001',now(),now()+interval '1 hour');
insert into public.clients(id,organization_id,name) values ('18210000-0000-0000-0000-000000000006','18210000-0000-0000-0000-000000000002','Synthetic client');
insert into public.form_templates(client_id,schema) values ('18210000-0000-0000-0000-000000000006','[{"id":"note","label":"Note","type":"text"}]');
insert into public.reports(id,client_id,helper_id,service_date,status,start_at,end_at) values ('18210000-0000-0000-0000-000000000007','18210000-0000-0000-0000-000000000006','18210000-0000-0000-0000-000000000001','2026-10-28','draft','2026-10-28 01:00+00','2026-10-28 02:00+00');
insert into public.report_values(report_id,data) values ('18210000-0000-0000-0000-000000000007','{"note":"before"}');
insert into private.mcp_record_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18210000-0000-0000-0000-000000000002',true,'{}','18210000-0000-0000-0000-000000000001',now());
insert into private.mcp_record_edit_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18210000-0000-0000-0000-000000000002',true,'{}','18210000-0000-0000-0000-000000000001',now());
select set_config('request.jwt.claims','{"sub":"18210000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18210000-0000-0000-0000-000000000003","session_id":"18210000-0000-0000-0000-000000000005"}',true);
create temp table proposal_id as select private.prepare_mcp_record_edit('18210000-0000-0000-0000-000000000002','18210000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18210000-0000-0000-0000-000000000007'),'{"note":"after"}','reason') as id;
select ok(not has_function_privilege('mcp_import','private.confirm_mcp_record_edit(uuid)','execute'),'MCP cannot confirm');
select ok(not has_function_privilege('authenticated','private.confirm_mcp_record_edit(uuid)','execute'),'browser cannot invoke internal function directly');
select throws_ok($$select private.confirm_mcp_record_edit((select id from proposal_id))$$,'42501','proposal_unavailable','OAuth session cannot confirm');
select set_config('request.jwt.claims','{"sub":"18210000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp182-browser"}',true);
savepoint stopped;
update private.mcp_record_edit_controls set enabled=false where organization_id='18210000-0000-0000-0000-000000000002';
select throws_ok($$select private.get_mcp_record_edit_review((select id from proposal_id))$$,'42501','proposal_unavailable','disabled control rejects review');
select throws_ok($$select private.confirm_mcp_record_edit((select id from proposal_id))$$,'42501','proposal_unavailable','disabled control rejects confirmation');
rollback to savepoint stopped;
savepoint revoked;
update auth.oauth_consents set revoked_at=clock_timestamp() where id='18210000-0000-0000-0000-000000000004';
select throws_ok($$select private.get_mcp_record_edit_review((select id from proposal_id))$$,'42501','proposal_unavailable','revoked OAuth rejects review');
select throws_ok($$select private.confirm_mcp_record_edit((select id from proposal_id))$$,'42501','proposal_unavailable','revoked OAuth rejects confirmation');
rollback to savepoint revoked;
savepoint lost_permission;
update public.organization_members set role='member' where organization_id='18210000-0000-0000-0000-000000000002' and user_id='18210000-0000-0000-0000-000000000001';
select throws_ok($$select private.get_mcp_record_edit_review((select id from proposal_id))$$,'42501','proposal_unavailable','permission removal rejects pending review');
select throws_ok($$select private.confirm_mcp_record_edit((select id from proposal_id))$$,'42501','proposal_unavailable','permission removal rejects pending confirmation');
rollback to savepoint lost_permission;
select ok(not has_function_privilege('mcp_import','private.get_mcp_record_edit_review(uuid)','execute'),'MCP cannot directly read internal review');
select is(private.get_mcp_record_edit_review((select id from proposal_id))->>'status','confirmation_required','browser can review pending proposal');
select is((select count(*)::int from public.audit_events where action_type='report.view' and resource_id='18210000-0000-0000-0000-000000000007'),1,'record review is audited');
savepoint stale;
update public.report_values set data='{"note":"concurrent"}' where report_id='18210000-0000-0000-0000-000000000007';
select is(private.get_mcp_record_edit_review((select id from proposal_id))->>'status','changed','review reports changed target');
select throws_ok($$select private.confirm_mcp_record_edit((select id from proposal_id))$$,'22023','proposal_changed','concurrent edit is rejected');
rollback to savepoint stale;
savepoint audit_failure;
create function public.mcp182_confirm_fail_audit() returns trigger language plpgsql set search_path='' as $$
begin if new.action_type='report.mcp_edit.confirm' then raise exception 'fixture_audit_failed'; end if; return new; end $$;
create trigger mcp182_confirm_fail_audit before insert on public.audit_events for each row execute function public.mcp182_confirm_fail_audit();
select throws_ok($$select private.confirm_mcp_record_edit((select id from proposal_id))$$,'P0001','fixture_audit_failed','audit failure rejects confirmation');
select is((select data->>'note' from public.report_values where report_id='18210000-0000-0000-0000-000000000007'),'before','audit failure rolls back record edit');
select is((select confirmed_at from private.mcp_record_edit_proposals where id=(select id from proposal_id)),null::timestamptz,'audit failure does not consume proposal');
rollback to savepoint audit_failure;
select is(private.confirm_mcp_record_edit((select id from proposal_id))->>'status','updated','browser confirmation saves draft');
select is((select data->>'note' from public.report_values where report_id='18210000-0000-0000-0000-000000000007'),'after','confirmed content is saved');
select is((select count(*)::int from public.audit_events where action_type='report.mcp_edit.confirm' and resource_id='18210000-0000-0000-0000-000000000007'),1,'confirmation is audited');
select is((private.confirm_mcp_record_edit((select id from proposal_id))->>'replayed')::boolean,true,'replayed confirmation returns existing result');
select is((select count(*)::int from public.audit_events where action_type='report.mcp_edit.confirm' and resource_id='18210000-0000-0000-0000-000000000007'),1,'replay does not duplicate audit');
insert into public.staffs(id,organization_id,name) values ('18210000-0000-0000-0000-000000000008','18210000-0000-0000-0000-000000000002','Synthetic staff');
select set_config('request.jwt.claims','{"sub":"18210000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18210000-0000-0000-0000-000000000003","session_id":"18210000-0000-0000-0000-000000000005"}',true);
create temp table metadata_id as select private.prepare_mcp_record_edit('18210000-0000-0000-0000-000000000002','18210000-0000-0000-0000-000000000007',(select current_version from public.reports where id='18210000-0000-0000-0000-000000000007'),'{"note":"after","travel_expenses":[{"staff_id":"18210000-0000-0000-0000-000000000008","staff_name":"incorrect","method":"car","amount_yen":200}],"travel_cost_yen":200}','metadata update','{"start_at":"2026-10-29T01:15:00Z","end_at":"2026-10-29T02:00:00Z","actual_staffs":[{"staff_id":"18210000-0000-0000-0000-000000000008"}]}') as id;
select set_config('request.jwt.claims','{"sub":"18210000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp182-browser"}',true);
select is(private.confirm_mcp_record_edit((select id from metadata_id))->>'status','updated','metadata update confirms');
select is((select start_at from public.reports where id='18210000-0000-0000-0000-000000000007'),'2026-10-29 01:15+00'::timestamptz,'confirmed time is saved');
select is((select service_date from public.reports where id='18210000-0000-0000-0000-000000000007'),'2026-10-29'::date,'date search uses the new Japan calendar date');
select is((select snapshot->'report'->>'service_date' from public.record_versions where resource_type='report' and resource_id='18210000-0000-0000-0000-000000000007' order by version_number desc limit 1),'2026-10-29','latest version contains the new service date');
select ok(exists(select 1 from public.record_versions where resource_type='report' and resource_id='18210000-0000-0000-0000-000000000007' and snapshot->'report'->>'service_date'='2026-10-28'),'previous version retains the original service date');
select is((select staff_id from public.report_actual_staffs where report_id='18210000-0000-0000-0000-000000000007'),'18210000-0000-0000-0000-000000000008'::uuid,'confirmed staff is saved');
select is((select data->'travel_expenses'->0->>'staff_name' from public.report_values where report_id='18210000-0000-0000-0000-000000000007'),'Synthetic staff','confirmed travel expense keeps server-derived name');
select is((select data->'_helpers'->>0 from public.report_values where report_id='18210000-0000-0000-0000-000000000007'),'Synthetic staff','confirmed helper name is derived from assigned staff');
savepoint date_boundary;
select set_config('care_record.skip_version','off',true);
update public.reports set start_at='2026-10-28 15:30+00' where id='18210000-0000-0000-0000-000000000007';
select is((select service_date from public.reports where id='18210000-0000-0000-0000-000000000007'),'2026-10-29'::date,'same Japan date remains unchanged across UTC midnight');
update public.reports set start_at='2026-10-28 14:30+00' where id='18210000-0000-0000-0000-000000000007';
select is((select service_date from public.reports where id='18210000-0000-0000-0000-000000000007'),'2026-10-28'::date,'direct update uses the Japan date when crossing midnight');
select is((select snapshot->>'service_date' from public.record_versions where resource_type='report' and resource_id='18210000-0000-0000-0000-000000000007' order by version_number desc limit 1),'2026-10-28','direct update captures the synchronized date in history');
rollback to savepoint date_boundary;
update public.reports set status='approved' where id='18210000-0000-0000-0000-000000000007';
create temp table approved_before as select r.current_version,r.current_revision_id,
  (select count(*) from public.record_versions v where v.resource_type='report' and v.resource_id=r.id) as versions
  from public.reports r where r.id='18210000-0000-0000-0000-000000000007';
select set_config('request.jwt.claims','{"sub":"18210000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18210000-0000-0000-0000-000000000003","session_id":"18210000-0000-0000-0000-000000000005"}',true);
create temp table correction_id as select private.prepare_mcp_record_edit('18210000-0000-0000-0000-000000000002','18210000-0000-0000-0000-000000000007',(select current_version from approved_before),(select data || '{"note":"proposed correction"}'::jsonb from public.report_values where report_id='18210000-0000-0000-0000-000000000007'),'reason for correction') as id;
select set_config('request.jwt.claims','{"sub":"18210000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp182-browser"}',true);
select is(private.confirm_mcp_record_edit((select id from correction_id))->>'status','correction_proposed','confirmed correction is saved as a proposal');
select is((select status from public.reports where id='18210000-0000-0000-0000-000000000007'),'approved','approved status is unchanged');
select is((select data->>'note' from public.report_values where report_id='18210000-0000-0000-0000-000000000007'),'after','approved record values are unchanged');
select is((select current_version from public.reports where id='18210000-0000-0000-0000-000000000007'),(select current_version from approved_before),'approved current version is unchanged');
select is((select count(*) from public.record_versions where resource_type='report' and resource_id='18210000-0000-0000-0000-000000000007'),(select versions from approved_before),'proposal does not create an official revision');
select is((select reason from private.mcp_record_edit_proposals where id=(select id from correction_id)),'reason for correction','correction reason is retained');
select is((select count(*)::int from public.audit_events where action_type='report.correction.proposed' and resource_id='18210000-0000-0000-0000-000000000007'),1,'saved correction proposal is audited');
update auth.oauth_consents set revoked_at=clock_timestamp() where id='18210000-0000-0000-0000-000000000004';
update private.mcp_record_edit_controls set enabled=false where organization_id='18210000-0000-0000-0000-000000000002';
select is(private.get_mcp_record_edit_review((select id from correction_id))->>'status','correction_proposed','confirmed proposal remains available to its authorized author after disconnection');
select is(private.get_mcp_record_edit_review((select id from correction_id))->'proposal'->'values'->>'note','proposed correction','saved correction content remains reviewable');
select is(jsonb_array_length(private.list_mcp_record_correction_proposals('18210000-0000-0000-0000-000000000002',20,0)->'proposals'),1,'saved correction appears in author list');
select ok(not (private.list_mcp_record_correction_proposals('18210000-0000-0000-0000-000000000002',20,0)->'proposals'->0 ? 'proposal'),'list omits sensitive proposal content');
update public.report_values set data='{"note":"later change"}' where report_id='18210000-0000-0000-0000-000000000007';
select is((private.get_mcp_record_edit_review((select id from correction_id))->>'base_changed')::boolean,true,'saved correction reports changes to the base');
update public.organization_members set role='member' where organization_id='18210000-0000-0000-0000-000000000002' and user_id='18210000-0000-0000-0000-000000000001';
select throws_ok($$select private.get_mcp_record_edit_review((select id from correction_id))$$,'42501','proposal_unavailable','saved correction is unavailable after permission removal');
select is(jsonb_array_length(private.list_mcp_record_correction_proposals('18210000-0000-0000-0000-000000000002',20,0)->'proposals'),0,'permission removal hides correction from list');
select * from finish();
rollback;
